 53 | void FrameConsole::AddMessage(ConsoleMessage* console_message,
 54 |                               bool discard_duplicates) {
 55 |   if (AddMessageToStorage(console_message, discard_duplicates)) {
 56 |     ReportMessageToClient(
 57 |         console_message->GetSource(), console_message->GetLevel(),
 58 |         console_message->Message(), console_message->Location());
 59 |   }
 60 | }
