 62 | bool FrameConsole::AddMessageToStorage(ConsoleMessage* console_message,
 63 |                                        bool discard_duplicates) {
 64 |   if (!frame_->DomWindow())
 65 |     return false;
 66 |   return frame_->GetPage()->GetConsoleMessageStorage().AddConsoleMessage(
 67 |       frame_->DomWindow(), console_message, discard_duplicates);
 68 | }
