 70 | void FrameConsole::ReportMessageToClient(
 71 |     mojom::blink::ConsoleMessageSource source,
 72 |     mojom::blink::ConsoleMessageLevel level,
 73 |     const String& message,
 74 |     SourceLocation* location) {
 75 |   if (source == mojom::blink::ConsoleMessageSource::kNetwork)
 76 |     return;
 77 | 
 78 |   String url = location->Url();
 79 |   String stack_trace;
 80 |   if (source == mojom::blink::ConsoleMessageSource::kConsoleApi) {
 81 |     if (!frame_->GetPage())
 82 |       return;
 83 |     if (frame_->GetChromeClient()
 84 |             .ShouldReportDetailedMessageForSourceAndSeverity(*frame_, level,
 85 |                                                              url)) {
 86 |       SourceLocation* full_location =
 87 |           SourceLocation::CaptureWithFullStackTrace();
 88 |       if (!full_location->IsUnknown())
 89 |         stack_trace = full_location->ToString();
 90 |     }
 91 |   } else {
 92 |     if (!location->IsUnknown() &&
 93 |         frame_->GetChromeClient()
 94 |             .ShouldReportDetailedMessageForSourceAndSeverity(*frame_, level,
 95 |                                                              url))
 96 |       stack_trace = location->ToString();
 97 |   }
 98 | 
 99 |   frame_->GetChromeClient().AddMessageToConsole(
100 |       frame_, source, level, message, location->LineNumber(), url, stack_trace);
101 | }
