103 | void FrameConsole::ReportResourceResponseReceived(
104 |     DocumentLoader* loader,
105 |     uint64_t request_identifier,
106 |     const ResourceResponse& response) {
107 |   if (!loader)
108 |     return;
109 |   if (response.HttpStatusCode() < 400)
110 |     return;
111 |   String message = Format(
112 |       "Failed to load resource: the server responded with a status of {} ({})",
113 |       response.HttpStatusCode(), response.HttpStatusText());
114 |   auto* console_message = MakeGarbageCollected<ConsoleMessage>(
115 |       mojom::blink::ConsoleMessageSource::kNetwork,
116 |       mojom::blink::ConsoleMessageLevel::kError, message,
117 |       response.CurrentRequestUrl().GetString(), loader, request_identifier);
118 |   AddMessage(console_message);
119 | }
