 132 | unsigned ThreadDebuggerCommonImpl::PromiseRejected(
 133 |     v8::Local<v8::Context> context,
 134 |     const String& error_message,
 135 |     v8::Local<v8::Value> exception,
 136 |     SourceLocation* location) {
 137 |   const StringView default_message = "Uncaught (in promise)";
 138 |   String message = error_message;
 139 |   if (message.empty()) {
 140 |     message = "Uncaught (in promise)";
 141 |   } else if (message.starts_with("Uncaught ")) {
 142 |     message = StrCat({"Uncaught (in promise)", StringView(message, 8)});
 143 |   }
 144 | 
 145 |   ReportConsoleMessage(ToExecutionContext(context),
 146 |                        mojom::ConsoleMessageSource::kJavaScript,
 147 |                        mojom::ConsoleMessageLevel::kError, message, location);
 148 |   String url = location->Url();
 149 |   return GetV8Inspector()->exceptionThrown(
 150 |       context, ToV8InspectorStringView(default_message), exception,
 151 |       ToV8InspectorStringView(message), ToV8InspectorStringView(url),
 152 |       location->LineNumber(), location->ColumnNumber(),
 153 |       location->TakeStackTrace(), location->ScriptId());
 154 | }
