 183 | 
 184 | v8::Local<v8::Object> SerializeNodeToV8Object(
 185 |     Node* node,
 186 |     v8::Isolate* isolate,
 187 |     int max_node_depth,
 188 |     ShadowTreeSerialization include_shadow_tree) {
 189 |   static const char kAttributes[] = "attributes";
 190 |   static const char kBackendNodeId[] = "backendNodeId";
 191 |   static const char kChildren[] = "children";
 192 |   static const char kChildNodeCount[] = "childNodeCount";
 193 |   static const char kLoaderId[] = "loaderId";
 194 |   static const char kLocalName[] = "localName";
 195 |   static const char kNamespaceURI[] = "namespaceURI";
 196 |   static const char kNode[] = "node";
 197 |   static const char kNodeType[] = "nodeType";
 198 |   static const char kNodeValue[] = "nodeValue";
 199 |   static const char kShadowRoot[] = "shadowRoot";
 200 |   static const char kShadowRootMode[] = "mode";
 201 |   static const char kShadowRootOpen[] = "open";
 202 |   static const char kShadowRootClosed[] = "closed";
 203 |   static const char kFrameIdParameterName[] = "frameId";
 204 | 
 205 |   v8::LocalVector<v8::Name> serialized_value_keys(isolate);
 206 |   v8::LocalVector<v8::Value> serialized_value_values(isolate);
 207 |   serialized_value_keys.push_back(V8String(isolate, kNodeType));
 208 |   serialized_value_values.push_back(
 209 |       v8::Number::New(isolate, node->getNodeType()));
 210 | 
 211 |   if (!node->nodeValue().IsNull()) {
 212 |     serialized_value_keys.push_back(V8String(isolate, kNodeValue));
 213 |     serialized_value_values.push_back(V8String(isolate, node->nodeValue()));
 214 |   }
 215 | 
 216 |   serialized_value_keys.push_back(V8String(isolate, kChildNodeCount));
 217 |   serialized_value_values.push_back(
 218 |       v8::Number::New(isolate, node->CountChildren()));
 219 | 
 220 |   DOMNodeId backend_node_id = node->GetDomNodeId();
 221 |   serialized_value_keys.push_back(V8String(isolate, kBackendNodeId));
 222 |   serialized_value_values.push_back(v8::Number::New(isolate, backend_node_id));
 223 | 
 224 |   serialized_value_keys.push_back(V8String(isolate, kLoaderId));
 225 |   serialized_value_values.push_back(V8String(
 226 |       isolate, IdentifiersFactory::LoaderId(node->GetDocument().Loader())));
 227 | 
 228 |   if (node->IsAttributeNode()) {
 229 |     Attr* attribute = To<Attr>(node);
 230 | 
 231 |     serialized_value_keys.push_back(V8String(isolate, kLocalName));
 232 |     serialized_value_values.push_back(
 233 |         V8String(isolate, attribute->localName()));
 234 | 
 235 |     serialized_value_keys.push_back(V8String(isolate, kNamespaceURI));
 236 |     if (attribute->namespaceURI().IsNull()) {
 237 |       serialized_value_values.push_back(v8::Null(isolate));
 238 |     } else {
 239 |       serialized_value_values.push_back(
 240 |           V8String(isolate, attribute->namespaceURI()));
 241 |     }
 242 |   }
 243 | 
 244 |   if (node->IsElementNode()) {
 245 |     Element* element = To<Element>(node);
 246 | 
 247 |     if (HTMLFrameOwnerElement* frameOwnerElement =
 248 |             DynamicTo<HTMLFrameOwnerElement>(node)) {
 249 |       if (frameOwnerElement->ContentFrame()) {
 250 |         serialized_value_keys.push_back(
 251 |             V8String(isolate, kFrameIdParameterName));
 252 |         serialized_value_values.push_back(V8String(
 253 |             isolate,
 254 |             IdentifiersFactory::IdFromToken(
 255 |                 frameOwnerElement->ContentFrame()->GetDevToolsFrameToken())));
 256 |       }
 257 |     }
 258 | 
 259 |     if (ShadowRoot* shadow_root = node->GetShadowRoot()) {
 260 |       // Do not decrease `max_node_depth` for shadow root. Shadow root should be
 261 |       // serialized fully, while it's children will be serialized respecting
 262 |       // max_node_depth and include_shadow_tree.
 263 |       v8::Local<v8::Object> serialized_shadow = SerializeNodeToV8Object(
 264 |           shadow_root, isolate, max_node_depth, include_shadow_tree);
 265 | 
 266 |       serialized_value_keys.push_back(V8String(isolate, kShadowRoot));
 267 |       serialized_value_values.push_back(serialized_shadow);
 268 |     } else {
 269 |       serialized_value_keys.push_back(V8String(isolate, kShadowRoot));
 270 |       serialized_value_values.push_back(v8::Null(isolate));
 271 |     }
 272 | 
 273 |     serialized_value_keys.push_back(V8String(isolate, kLocalName));
 274 |     serialized_value_values.push_back(V8String(isolate, element->localName()));
 275 | 
 276 |     serialized_value_keys.push_back(V8String(isolate, kNamespaceURI));
 277 |     serialized_value_values.push_back(
 278 |         V8String(isolate, element->namespaceURI()));
 279 | 
 280 |     v8::LocalVector<v8::Name> node_attributes_keys(isolate);
 281 |     v8::LocalVector<v8::Value> node_attributes_values(isolate);
 282 | 
 283 |     for (const Attribute& attribute : element->Attributes()) {
 284 |       node_attributes_keys.push_back(
 285 |           V8String(isolate, attribute.GetName().ToString()));
 286 |       node_attributes_values.push_back(V8String(isolate, attribute.Value()));
 287 |     }
 288 | 
 289 |     DCHECK(node_attributes_values.size() == node_attributes_keys.size());
 290 |     v8::Local<v8::Object> node_attributes = v8::Object::New(
 291 |         isolate, v8::Null(isolate), node_attributes_keys.data(),
 292 |         node_attributes_values.data(), node_attributes_keys.size());
 293 | 
 294 |     serialized_value_keys.push_back(V8String(isolate, kAttributes));
 295 |     serialized_value_values.push_back(node_attributes);
 296 |   }
 297 | 
 298 |   bool include_children = max_node_depth > 0;
 299 |   if (node->IsShadowRoot()) {
 300 |     ShadowRoot* shadow_root = To<ShadowRoot>(node);
 301 | 
 302 |     // Include children of shadow root only if `max_depth` is not reached and
 303 |     // one of the following is true:
 304 |     // 1. `include_shadow_tree` set to `all` regardless of the shadow type.
 305 |     // 2. `include_shadow_tree` set to `open` and the shadow type is `open`.
 306 |     if (include_shadow_tree == kNone) {
 307 |       include_children = false;
 308 |     } else if (include_shadow_tree == kOpen &&
 309 |                shadow_root->GetMode() != ShadowRootMode::kOpen) {
 310 |       include_children = false;
 311 |     }
 312 | 
 313 |     serialized_value_keys.push_back(V8String(isolate, kShadowRootMode));
 314 |     serialized_value_values.push_back(
 315 |         V8String(isolate, shadow_root->GetMode() == ShadowRootMode::kOpen
 316 |                               ? kShadowRootOpen
 317 |                               : kShadowRootClosed));
 318 |   }
 319 | 
 320 |   if (include_children) {
 321 |     NodeList* child_nodes = node->childNodes();
 322 | 
 323 |     v8::Local<v8::Array> children =
 324 |         v8::Array::New(isolate, child_nodes->length());
 325 | 
 326 |     for (unsigned int i = 0; i < child_nodes->length(); i++) {
 327 |       Node* child_node = child_nodes->item(i);
 328 |       v8::Local<v8::Object> serialized_child_node = SerializeNodeToV8Object(
 329 |           child_node, isolate, max_node_depth - 1, include_shadow_tree);
 330 | 
 331 |       children
 332 |           ->CreateDataProperty(isolate->GetCurrentContext(), i,
 333 |                                serialized_child_node)
 334 |           .Check();
 335 |     }
 336 |     serialized_value_keys.push_back(V8String(isolate, kChildren));
 337 |     serialized_value_values.push_back(children);
 338 |   }
 339 | 
 340 |   DCHECK(serialized_value_values.size() == serialized_value_keys.size());
 341 | 
 342 |   v8::Local<v8::Object> serialized_value = v8::Object::New(
 343 |       isolate, v8::Null(isolate), serialized_value_keys.data(),
 344 |       serialized_value_values.data(), serialized_value_keys.size());
 345 | 
 346 |   v8::LocalVector<v8::Name> result_keys(isolate);
 347 |   v8::LocalVector<v8::Value> result_values(isolate);
 348 | 
 349 |   result_keys.push_back(TypeStringKey(isolate));
 350 |   result_values.push_back(V8String(isolate, kNode));
 351 | 
 352 |   result_keys.push_back(ValueStringKey(isolate));
 353 |   result_values.push_back(serialized_value);
 354 | 
 355 |   return v8::Object::New(isolate, v8::Null(isolate), result_keys.data(),
 356 |                          result_values.data(), result_keys.size());
 357 | }
