 359 | std::unique_ptr<v8_inspector::DeepSerializedValue> DeepSerializeHtmlCollection(
 360 |     HTMLCollection* html_collection,
 361 |     v8::Isolate* isolate_,
 362 |     int max_depth,
 363 |     int max_node_depth,
 364 |     ShadowTreeSerialization include_shadow_tree) {
 365 |   static const char kHtmlCollection[] = "htmlcollection";
 366 |   if (max_depth > 0) {
 367 |     v8::Local<v8::Array> children =
 368 |         v8::Array::New(isolate_, html_collection->length());
 369 | 
 370 |     for (unsigned int i = 0; i < html_collection->length(); i++) {
 371 |       Node* child_node = html_collection->item(i);
 372 |       v8::Local<v8::Object> serialized_child_node = SerializeNodeToV8Object(
 373 |           child_node, isolate_, max_node_depth, include_shadow_tree);
 374 |       children
 375 |           ->CreateDataProperty(isolate_->GetCurrentContext(), i,
 376 |                                serialized_child_node)
 377 |           .Check();
 378 |     }
 379 |     return std::make_unique<v8_inspector::DeepSerializedValue>(
 380 |         ToV8InspectorStringBuffer(kHtmlCollection), children);
 381 |   }
 382 | 
 383 |   return std::make_unique<v8_inspector::DeepSerializedValue>(
 384 |       ToV8InspectorStringBuffer(kHtmlCollection));
 385 | }
