 387 | std::unique_ptr<v8_inspector::DeepSerializedValue> DeepSerializeNodeList(
 388 |     NodeList* node_list,
 389 |     v8::Isolate* isolate_,
 390 |     int max_depth,
 391 |     int max_node_depth,
 392 |     ShadowTreeSerialization include_shadow_tree) {
 393 |   static const char kNodeList[] = "nodelist";
 394 |   if (max_depth > 0) {
 395 |     v8::Local<v8::Array> children =
 396 |         v8::Array::New(isolate_, node_list->length());
 397 | 
 398 |     for (unsigned int i = 0; i < node_list->length(); i++) {
 399 |       Node* child_node = node_list->item(i);
 400 |       v8::Local<v8::Object> serialized_child_node = SerializeNodeToV8Object(
 401 |           child_node, isolate_, max_node_depth, include_shadow_tree);
 402 |       children
 403 |           ->CreateDataProperty(isolate_->GetCurrentContext(), i,
 404 |                                serialized_child_node)
 405 |           .Check();
 406 |     }
 407 |     return std::make_unique<v8_inspector::DeepSerializedValue>(
 408 |         ToV8InspectorStringBuffer(kNodeList), children);
 409 |   }
 410 | 
 411 |   return std::make_unique<v8_inspector::DeepSerializedValue>(
 412 |       ToV8InspectorStringBuffer(kNodeList));
 413 | }
