 415 | std::unique_ptr<v8_inspector::DeepSerializedValue> DeepSerializeNode(
 416 |     Node* node,
 417 |     v8::Isolate* isolate,
 418 |     int max_node_depth,
 419 |     ShadowTreeSerialization include_shadow_tree) {
 420 |   v8::Local<v8::Object> node_v8_object = SerializeNodeToV8Object(
 421 |       node, isolate, max_node_depth, include_shadow_tree);
 422 | 
 423 |   v8::Local<v8::Value> value_v8_object =
 424 |       node_v8_object->Get(isolate->GetCurrentContext(), ValueStringKey(isolate))
 425 |           .ToLocalChecked();
 426 | 
 427 |   // Safely get `type` from object value.
 428 |   v8::MaybeLocal<v8::Value> maybe_type_v8_value =
 429 |       node_v8_object->Get(isolate->GetCurrentContext(), TypeStringKey(isolate));
 430 |   DCHECK(!maybe_type_v8_value.IsEmpty());
 431 |   v8::Local<v8::Value> type_v8_value = maybe_type_v8_value.ToLocalChecked();
 432 |   DCHECK(type_v8_value->IsString());
 433 |   v8::Local<v8::String> type_v8_string = type_v8_value.As<v8::String>();
 434 |   String type_string = ToCoreString(isolate, type_v8_string);
 435 |   StringView type_string_view = StringView(type_string);
 436 |   std::unique_ptr<v8_inspector::StringBuffer> type_string_buffer =
 437 |       ToV8InspectorStringBuffer(type_string_view);
 438 | 
 439 |   return std::make_unique<v8_inspector::DeepSerializedValue>(
 440 |       std::move(type_string_buffer), value_v8_object);
 441 | }
