 630 | std::unique_ptr<v8_inspector::StringBuffer>
 631 | ThreadDebuggerCommonImpl::descriptionForValueSubtype(
 632 |     v8::Local<v8::Context> context,
 633 |     v8::Local<v8::Value> value) {
 634 |   if (TrustedHTML* trusted_html = V8TrustedHTML::ToWrappable(isolate_, value)) {
 635 |     return ToV8InspectorStringBuffer(trusted_html->toString());
 636 |   } else if (TrustedScript* trusted_script =
 637 |                  V8TrustedScript::ToWrappable(isolate_, value)) {
 638 |     return ToV8InspectorStringBuffer(trusted_script->toString());
 639 |   } else if (TrustedScriptURL* trusted_script_url =
 640 |                  V8TrustedScriptURL::ToWrappable(isolate_, value)) {
 641 |     return ToV8InspectorStringBuffer(trusted_script_url->toString());
 642 |   } else if (Node* node = V8Node::ToWrappable(isolate_, value)) {
 643 |     StringBuilder description;
 644 |     switch (node->getNodeType()) {
 645 |       case Node::kElementNode: {
 646 |         const auto* element = To<blink::Element>(node);
 647 |         description.Append(element->TagQName().ToString());
 648 | 
 649 |         const AtomicString& id = element->GetIdAttribute();
 650 |         if (!id.empty()) {
 651 |           description.Append('#');
 652 |           description.Append(id);
 653 |         }
 654 |         if (element->HasClass()) {
 655 |           auto element_class_names = element->ClassNames();
 656 |           auto n_classes = element_class_names.size();
 657 |           for (unsigned i = 0; i < n_classes; ++i) {
 658 |             description.Append('.');
 659 |             description.Append(element_class_names[i]);
 660 |           }
 661 |         }
 662 |         break;
 663 |       }
 664 |       case Node::kDocumentTypeNode: {
 665 |         description.Append("<!DOCTYPE ");
 666 |         description.Append(node->nodeName());
 667 |         description.Append('>');
 668 |         break;
 669 |       }
 670 |       default: {
 671 |         description.Append(node->nodeName());
 672 |         break;
 673 |       }
 674 |     }
 675 |     DCHECK(description.length());
 676 | 
 677 |     return ToV8InspectorStringBuffer(description);
 678 |   }
 679 |   return nullptr;
 680 | }
