 696 | static v8::Maybe<bool> CreateDataProperty(v8::Local<v8::Context> context,
 697 |                                           v8::Local<v8::Object> object,
 698 |                                           v8::Local<v8::Name> key,
 699 |                                           v8::Local<v8::Value> value) {
 700 |   v8::TryCatch try_catch(v8::Isolate::GetCurrent());
 701 |   v8::Isolate::DisallowJavascriptExecutionScope throw_js(
 702 |       v8::Isolate::GetCurrent(),
 703 |       v8::Isolate::DisallowJavascriptExecutionScope::THROW_ON_FAILURE);
 704 |   return object->CreateDataProperty(context, key, value);
