 707 | static void CreateFunctionPropertyWithData(
 708 |     v8::Local<v8::Context> context,
 709 |     v8::Local<v8::Object> object,
 710 |     const char* name,
 711 |     v8::FunctionCallback callback,
 712 |     v8::Local<v8::Value> data,
 713 |     const char* description,
 714 |     v8::SideEffectType side_effect_type) {
 715 |   v8::Local<v8::String> func_name = V8String(v8::Isolate::GetCurrent(), name);
 716 |   v8::Local<v8::Function> func;
 717 |   if (!v8::Function::New(context, callback, data, 0,
 718 |                          v8::ConstructorBehavior::kThrow, side_effect_type)
 719 |            .ToLocal(&func))
 720 |     return;
 721 |   func->SetName(func_name);
 722 |   v8::Local<v8::String> return_value =
 723 |       V8String(v8::Isolate::GetCurrent(), description);
 724 |   v8::Local<v8::Function> to_string_function;
 725 |   if (v8::Function::New(context, ReturnDataCallback, return_value, 0,
 726 |                         v8::ConstructorBehavior::kThrow,
 727 |                         v8::SideEffectType::kHasNoSideEffect)
 728 |           .ToLocal(&to_string_function))
 729 |     CreateDataProperty(context, func,
 730 |                        V8AtomicString(v8::Isolate::GetCurrent(), "toString"),
 731 |                        to_string_function);
 732 |   CreateDataProperty(context, object, func_name, func);
 733 | }
