 812 | static Vector<String> NormalizeEventTypes(
 813 |     const v8::FunctionCallbackInfo<v8::Value>& info) {
 814 |   Vector<String> types;
 815 |   v8::Isolate* isolate = info.GetIsolate();
 816 |   if (info.Length() > 1 && info[1]->IsString())
 817 |     types.push_back(ToCoreString(isolate, info[1].As<v8::String>()));
 818 |   if (info.Length() > 1 && info[1]->IsArray()) {
 819 |     v8::Local<v8::Array> types_array = v8::Local<v8::Array>::Cast(info[1]);
 820 |     for (wtf_size_t i = 0; i < types_array->Length(); ++i) {
 821 |       v8::Local<v8::Value> type_value;
 822 |       if (!types_array->Get(isolate->GetCurrentContext(), i)
 823 |                .ToLocal(&type_value) ||
 824 |           !type_value->IsString()) {
 825 |         continue;
 826 |       }
 827 |       types.push_back(
 828 |           ToCoreString(isolate, v8::Local<v8::String>::Cast(type_value)));
 829 |     }
 830 |   }
 831 |   if (info.Length() == 1) {
 832 |     static constexpr std::string_view kAllEvents[] = {
 833 |         "mouse",   "key",          "touch",
 834 |         "pointer", "control",      "load",
 835 |         "unload",  "abort",        "error",
 836 |         "select",  "input",        "change",
 837 |         "submit",  "reset",        "focus",
 838 |         "blur",    "resize",       "scroll",
 839 |         "search",  "devicemotion", "deviceorientation",
 840 |     };
 841 |     types.append_range(kAllEvents);
 842 |   }
 843 | 
 844 |   Vector<String> output_types;
 845 |   for (wtf_size_t i = 0; i < types.size(); ++i) {
 846 |     if (types[i] == "mouse") {
 847 |       static constexpr std::string_view kMouseEvents[] = {
 848 |           "auxclick",    "click",      "dblclick",   "mousedown",
 849 |           "mouseeenter", "mouseleave", "mousemove",  "mouseout",
 850 |           "mouseover",   "mouseup",    "mouseleave", "mousewheel"};
 851 |       output_types.append_range(kMouseEvents);
 852 |     } else if (types[i] == "key") {
 853 |       static constexpr std::string_view kKeyEvents[] = {
 854 |           "keydown", "keyup", "keypress", "textInput"};
 855 |       output_types.append_range(kKeyEvents);
 856 |     } else if (types[i] == "touch") {
 857 |       static constexpr std::string_view kTouchEvents[] = {
 858 |           "touchstart", "touchmove", "touchend", "touchcancel"};
 859 |       output_types.append_range(kTouchEvents);
 860 |     } else if (types[i] == "pointer") {
 861 |       static constexpr std::string_view kPointerEvents[] = {
 862 |           "pointerover",       "pointerout",    "pointerenter",
 863 |           "pointerleave",      "pointerdown",   "pointerup",
 864 |           "pointermove",       "pointercancel", "gotpointercapture",
 865 |           "lostpointercapture"};
 866 |       output_types.append_range(kPointerEvents);
 867 |     } else if (types[i] == "control") {
 868 |       static constexpr std::string_view kControlEvents[] = {
 869 |           "resize", "scroll", "zoom",   "focus",  "blur",
 870 |           "select", "input",  "change", "submit", "reset"};
 871 |       output_types.append_range(kControlEvents);
 872 |     } else {
 873 |       output_types.push_back(types[i]);
 874 |     }
 875 |   }
 876 |   return output_types;
 877 | }
