 879 | static EventTarget* FirstArgumentAsEventTarget(
 880 |     const v8::FunctionCallbackInfo<v8::Value>& info) {
 881 |   if (info.Length() < 1)
 882 |     return nullptr;
 883 |   return V8EventTarget::ToWrappable(info.GetIsolate(), info[0]);
