466 | bool ReadAdditionalSerializationParameters(
467 |     v8::Local<v8::Object> additional_parameters,
468 |     int& max_node_depth,
469 |     ShadowTreeSerialization& include_shadow_tree,
470 |     v8::Local<v8::Context> context,
471 |     std::unique_ptr<v8_inspector::StringBuffer>* error_message) {
472 |   static const char kMaxNodeDepthParameterName[] = "maxNodeDepth";
473 |   static const char kIncludeShadowTreeParameterName[] = "includeShadowTree";
474 |   static const char kIncludeShadowTreeValueNone[] = "none";
475 |   static const char kIncludeShadowTreeValueOpen[] = "open";
476 |   static const char kIncludeShadowTreeValueAll[] = "all";
477 | 
478 |   // Set default values.
479 |   max_node_depth = 0;
480 |   include_shadow_tree = ShadowTreeSerialization::kNone;
481 | 
482 |   if (additional_parameters.IsEmpty()) {
483 |     return true;
484 |   }
485 | 
486 |   v8::MaybeLocal<v8::Value> include_shadow_tree_parameter =
487 |       additional_parameters->Get(
488 |           context,
489 |           V8String(v8::Isolate::GetCurrent(), kIncludeShadowTreeParameterName));
490 |   if (!include_shadow_tree_parameter.IsEmpty()) {
491 |     v8::Local<v8::Value> include_shadow_tree_value =
492 |         include_shadow_tree_parameter.ToLocalChecked();
493 |     if (!include_shadow_tree_value->IsUndefined()) {
494 |       if (!include_shadow_tree_value->IsString()) {
495 |         *error_message = ToV8InspectorStringBuffer(
496 |             StrCat({"Parameter ", kIncludeShadowTreeParameterName,
497 |                     " should be of type string."}));
498 |         return false;
499 |       }
500 |       String include_shadow_tree_string =
501 |           ToCoreString(v8::Isolate::GetCurrent(),
502 |                        include_shadow_tree_value.As<v8::String>());
503 | 
504 |       if (include_shadow_tree_string == kIncludeShadowTreeValueNone) {
505 |         include_shadow_tree = ShadowTreeSerialization::kNone;
506 |       } else if (include_shadow_tree_string == kIncludeShadowTreeValueOpen) {
507 |         include_shadow_tree = ShadowTreeSerialization::kOpen;
508 |       } else if (include_shadow_tree_string == kIncludeShadowTreeValueAll) {
509 |         include_shadow_tree = ShadowTreeSerialization::kAll;
510 |       } else {
511 |         *error_message = ToV8InspectorStringBuffer(
512 |             StrCat({"Unknown value ", kIncludeShadowTreeParameterName, ":",
513 |                     include_shadow_tree_string}));
514 |         return false;
515 |       }
516 |     }
517 |   }
518 | 
519 |   v8::MaybeLocal<v8::Value> max_node_depth_parameter =
520 |       additional_parameters->Get(context, V8String(v8::Isolate::GetCurrent(),
521 |                                                    kMaxNodeDepthParameterName));
522 |   if (!max_node_depth_parameter.IsEmpty()) {
523 |     v8::Local<v8::Value> max_node_depth_value =
524 |         max_node_depth_parameter.ToLocalChecked();
525 |     if (!max_node_depth_value->IsUndefined()) {
526 |       if (!max_node_depth_value->IsInt32()) {
527 |         *error_message = ToV8InspectorStringBuffer(
528 |             StrCat({"Parameter ", kMaxNodeDepthParameterName,
529 |                     " should be of type int."}));
530 |         return false;
531 |       }
532 |       max_node_depth = max_node_depth_value.As<v8::Int32>()->Value();
533 |     }
534 |   }
535 |   return true;
536 | }
