538 | std::unique_ptr<v8_inspector::DeepSerializationResult>
539 | ThreadDebuggerCommonImpl::deepSerialize(
540 |     v8::Local<v8::Value> v8_value,
541 |     int max_depth,
542 |     v8::Local<v8::Object> additional_parameters) {
543 |   int max_node_depth;
544 |   ShadowTreeSerialization include_shadow_tree;
545 | 
546 |   std::unique_ptr<v8_inspector::StringBuffer> error_message;
547 |   bool success = ReadAdditionalSerializationParameters(
548 |       additional_parameters, max_node_depth, include_shadow_tree,
549 |       isolate_->GetCurrentContext(), &error_message);
550 |   if (!success) {
551 |     return std::make_unique<v8_inspector::DeepSerializationResult>(
552 |         std::move(error_message));
553 |   }
554 | 
555 |   if (!v8_value->IsObject()) {
556 |     return nullptr;
557 |   }
558 |   v8::Local<v8::Object> object = v8_value.As<v8::Object>();
559 | 
560 |   // Serialize according to https://w3c.github.io/webdriver-bidi.
561 |   if (Node* node = V8Node::ToWrappable(isolate_, object)) {
562 |     return std::make_unique<v8_inspector::DeepSerializationResult>(
563 |         DeepSerializeNode(node, isolate_, max_node_depth, include_shadow_tree));
564 |   }
565 | 
566 |   // Serialize as a regular array
567 |   if (HTMLCollection* html_collection =
568 |           V8HTMLCollection::ToWrappable(isolate_, object)) {
569 |     return std::make_unique<v8_inspector::DeepSerializationResult>(
570 |         DeepSerializeHtmlCollection(html_collection, isolate_, max_depth,
571 |                                     max_node_depth, include_shadow_tree));
572 |   }
573 | 
574 |   // Serialize as a regular array
575 |   if (NodeList* node_list = V8NodeList::ToWrappable(isolate_, object)) {
576 |     return std::make_unique<v8_inspector::DeepSerializationResult>(
577 |         DeepSerializeNodeList(node_list, isolate_, max_depth, max_node_depth,
578 |                               include_shadow_tree));
579 |   }
580 | 
581 |   if (DOMWindow* window = V8Window::ToWrappable(isolate_, object)) {
582 |     return std::make_unique<v8_inspector::DeepSerializationResult>(
583 |         DeepSerializeWindow(window, isolate_));
584 |   }
585 | 
586 |   // TODO(caseq): consider object->IsApiWrapper() + checking for all kinds
587 |   // of (Typed)?Array(Buffers)?. IsApiWrapper() returns true for these, but
588 |   // we want them to fall through to default serialization and not be treated
589 |   // as "platform objects".
590 |   if (V8DOMWrapper::IsWrapper(isolate_, object)) {
591 |     return std::make_unique<v8_inspector::DeepSerializationResult>(
592 |         std::make_unique<v8_inspector::DeepSerializedValue>(
593 |             ToV8InspectorStringBuffer("platformobject")));
594 |   }
595 | 
596 |   return nullptr;
597 | }
