123 | void MainThreadDebugger::ContextCreated(ScriptState* script_state,
124 |                                         LocalFrame* frame,
125 |                                         const SecurityOrigin* origin) {
126 |   DCHECK(IsMainThread());
127 |   v8::HandleScope handles(script_state->GetIsolate());
128 |   DOMWrapperWorld& world = script_state->World();
129 |   StringBuilder aux_data_builder;
130 |   aux_data_builder.Append("{\"isDefault\":");
131 |   aux_data_builder.Append(world.IsMainWorld() ? "true" : "false");
132 |   if (world.IsMainWorld()) {
133 |     aux_data_builder.Append(",\"type\":\"default\"");
134 |   } else if (world.IsIsolatedWorld()) {
135 |     aux_data_builder.Append(",\"type\":\"isolated\"");
136 |   } else if (world.IsWorkerOrWorkletWorld()) {
137 |     aux_data_builder.Append(",\"type\":\"worker\"");
