139 |   aux_data_builder.Append(",\"frameId\":\"");
140 |   aux_data_builder.Append(IdentifiersFactory::FrameId(frame));
141 |   aux_data_builder.Append("\"}");
142 |   String aux_data = aux_data_builder.ToString();
143 |   String human_readable_name =
144 |       !world.IsMainWorld() ? world.NonMainWorldHumanReadableName() : String();
145 |   String origin_string = origin ? origin->ToRawString() : String();
146 |   v8_inspector::V8ContextInfo context_info(
147 |       script_state->GetContext(), ContextGroupId(frame),
148 |       ToV8InspectorStringView(human_readable_name));
149 |   context_info.origin = ToV8InspectorStringView(origin_string);
150 |   context_info.auxData = ToV8InspectorStringView(aux_data);
