160 | void MainThreadDebugger::ExceptionThrown(ExecutionContext* context,
161 |                                          ErrorEvent* event) {
162 |   LocalFrame* frame = nullptr;
163 |   ScriptState* script_state = nullptr;
164 |   if (auto* window = DynamicTo<LocalDOMWindow>(context)) {
165 |     frame = window->GetFrame();
166 |     if (!frame)
167 |       return;
168 |     script_state =
169 |         event->World() ? ToScriptState(frame, *event->World()) : nullptr;
170 |   } else if (context->IsMainThreadWorkletGlobalScope()) {
171 |     auto* scope = To<WorkletGlobalScope>(context);
172 |     frame = scope->GetFrame();
173 |     if (!frame)
174 |       return;
175 |     script_state = scope->ScriptController()->GetScriptState();
176 |   } else {
177 |     NOTREACHED();
178 |   }
179 | 
180 |   frame->Console().ReportMessageToClient(
181 |       mojom::ConsoleMessageSource::kJavaScript,
182 |       mojom::ConsoleMessageLevel::kError, event->MessageForConsole(),
183 |       event->Location());
184 | 
185 |   const String default_message = "Uncaught";
186 |   if (script_state && script_state->ContextIsValid()) {
187 |     ScriptState::Scope scope(script_state);
188 |     ScriptValue error = event->error(script_state);
189 |     v8::Local<v8::Value> exception =
190 |         error.IsEmpty()
191 |             ? v8::Local<v8::Value>(v8::Null(script_state->GetIsolate()))
192 |             : error.V8Value();
193 | 
194 |     SourceLocation* location = event->Location();
195 |     String message = event->MessageForConsole();
196 |     String url = location->Url();
197 |     GetV8Inspector()->exceptionThrown(
198 |         script_state->GetContext(), ToV8InspectorStringView(default_message),
199 |         exception, ToV8InspectorStringView(message),
200 |         ToV8InspectorStringView(url), location->LineNumber(),
201 |         location->ColumnNumber(), location->TakeStackTrace(),
202 |         location->ScriptId());
203 |   }
204 | }
