218 | void MainThreadDebugger::runMessageLoopOnInstrumentationPause(
219 |     int context_group_id) {
220 |   LocalFrame* paused_frame =
221 |       WeakIdentifierMap<LocalFrame>::Lookup(context_group_id);
222 |   // Do not pause in Context of detached frame.
223 |   if (!paused_frame) {
224 |     return;
225 |   }
226 | 
227 |   DCHECK_EQ(paused_frame, &paused_frame->LocalFrameRoot());
228 |   paused_ = true;
229 | 
230 |   // Wait until the execution gets resumed.
231 |   if (client_message_loop_) {
232 |     client_message_loop_->Run(paused_frame,
233 |                               ClientMessageLoop::kInstrumentationPause);
234 |   }
235 | }
236 | 
237 | void MainThreadDebugger::runMessageLoopOnPause(int context_group_id) {
238 |   LocalFrame* paused_frame =
239 |       WeakIdentifierMap<LocalFrame>::Lookup(context_group_id);
240 |   // Do not pause in Context of detached frame.
241 |   if (!paused_frame)
242 |     return;
243 |   // If we hit a break point in the paint() function for CSS paint, then we are
244 |   // in the middle of document life cycle. In this case, we should not allow
245 |   // any style update or layout, which could be triggered by resizing the
246 |   // browser window, or clicking at the element panel on devtool.
247 |   if (paused_frame->GetDocument() &&
248 |       !paused_frame->GetDocument()->Lifecycle().StateAllowsTreeMutations()) {
249 |     postponed_transition_scope_ =
250 |         std::make_unique<DocumentLifecycle::PostponeTransitionScope>(
251 |             paused_frame->GetDocument()->Lifecycle());
252 |   }
253 |   DCHECK_EQ(paused_frame, &paused_frame->LocalFrameRoot());
254 |   paused_ = true;
255 | 
256 |   // Wait for continue or step command.
257 |   if (client_message_loop_)
258 |     client_message_loop_->Run(paused_frame, ClientMessageLoop::kNormalPause);
259 | }
260 | 
261 | void MainThreadDebugger::quitMessageLoopOnPause() {
262 |   paused_ = false;
263 |   postponed_transition_scope_.reset();
264 |   if (client_message_loop_)
265 |     client_message_loop_->QuitNow();
266 | }
