288 | v8::Local<v8::Context> MainThreadDebugger::ensureDefaultContextInGroup(
289 |     int context_group_id) {
290 |   LocalFrame* frame = WeakIdentifierMap<LocalFrame>::Lookup(context_group_id);
291 |   if (!frame)
292 |     return v8::Local<v8::Context>();
293 | 
294 |   // This is a workaround code with a bailout to avoid crashing in
295 |   // LocalWindowProxy::Initialize().
296 |   // We cannot request a ScriptState on a provisional frame as it would lead
297 |   // to a context creation on it, which is not allowed. Remove this extra check
298 |   // when provisional frames concept gets eliminated. See crbug.com/897816
299 |   // The DCHECK is kept to catch additional regressions earlier.
300 |   // TODO(crbug.com/1182538): DCHECKs are disabled during automated testing on
301 |   // CrOS and this check failed when tested on an experimental builder. Revert
302 |   // https://crrev.com/c/2727867 to enable it.
303 |   // See go/chrome-dcheck-on-cros or http://crbug.com/1113456 for more details.
304 | #if !BUILDFLAG(IS_CHROMEOS)
305 |   DCHECK(!frame->IsProvisional());
306 | #endif
307 |   if (frame->IsProvisional())
308 |     return v8::Local<v8::Context>();
309 | 
310 |   ScriptState* script_state = ToScriptStateForMainWorld(frame);
311 |   return script_state ? script_state->GetContext() : v8::Local<v8::Context>();
312 | }
