402 | void MainThreadDebugger::QuerySelectorCallback(
403 |     const v8::FunctionCallbackInfo<v8::Value>& info) {
404 |   if (info.Length() < 1)
405 |     return;
406 |   const String& selector =
407 |       ToCoreStringWithUndefinedOrNullCheck(info.GetIsolate(), info[0]);
408 |   if (selector.empty())
409 |     return;
410 |   auto* container_node = DynamicTo<ContainerNode>(SecondArgumentAsNode(info));
411 |   if (!container_node)
412 |     return;
413 |   ScriptState* script_state = ScriptState::ForCurrentRealm(info);
414 |   v8::TryCatch try_catch(info.GetIsolate());
415 |   Element* element = container_node->QuerySelector(
416 |       AtomicString(selector), PassThroughException(info.GetIsolate()));
417 |   if (try_catch.HasCaught()) {
418 |     ApplyContextToException(script_state, try_catch.Exception(),
419 |                             v8::ExceptionContext::kOperation, "CommandLineAPI",
420 |                             "$");
421 |     try_catch.ReThrow();
422 |     return;
423 |   }
424 |   if (element) {
425 |     info.GetReturnValue().Set(ToV8Traits<Element>::ToV8(script_state, element));
426 |   } else {
427 |     info.GetReturnValue().Set(v8::Null(info.GetIsolate()));
428 |   }
429 | }
430 | 
431 | void MainThreadDebugger::QuerySelectorAllCallback(
432 |     const v8::FunctionCallbackInfo<v8::Value>& info) {
433 |   if (info.Length() < 1)
434 |     return;
435 |   const String& selector =
436 |       ToCoreStringWithUndefinedOrNullCheck(info.GetIsolate(), info[0]);
437 |   if (selector.empty())
438 |     return;
439 |   auto* container_node = DynamicTo<ContainerNode>(SecondArgumentAsNode(info));
440 |   if (!container_node)
441 |     return;
442 |   ScriptState* script_state = ScriptState::ForCurrentRealm(info);
443 |   v8::TryCatch try_catch(info.GetIsolate());
444 |   // ToV8(elementList) doesn't work here, since we need a proper Array instance,
445 |   // not NodeList.
446 |   StaticElementList* element_list = container_node->QuerySelectorAll(
447 |       AtomicString(selector), PassThroughException(info.GetIsolate()));
448 |   if (try_catch.HasCaught()) {
449 |     ApplyContextToException(script_state, try_catch.Exception(),
450 |                             v8::ExceptionContext::kOperation, "CommandLineAPI",
451 |                             "$$");
452 |     try_catch.ReThrow();
453 |     return;
454 |   }
455 |   if (!element_list) {
456 |     return;
457 |   }
458 |   v8::Isolate* isolate = info.GetIsolate();
459 |   v8::Local<v8::Context> context = isolate->GetCurrentContext();
460 |   v8::Local<v8::Array> nodes = v8::Array::New(isolate, element_list->length());
461 |   for (wtf_size_t i = 0; i < element_list->length(); ++i) {
462 |     Element* element = element_list->item(i);
463 |     v8::Local<v8::Value> value =
464 |         ToV8Traits<Element>::ToV8(script_state, element);
465 |     if (!CreateDataPropertyInArray(context, nodes, i, value).FromMaybe(false)) {
466 |       return;
467 |     }
468 |   }
469 |   info.GetReturnValue().Set(nodes);
470 | }
471 | 
472 | void MainThreadDebugger::XpathSelectorCallback(
473 |     const v8::FunctionCallbackInfo<v8::Value>& info) {
474 |   if (info.Length() < 1)
475 |     return;
476 |   v8::Isolate* isolate = info.GetIsolate();
477 |   const String& selector =
478 |       ToCoreStringWithUndefinedOrNullCheck(isolate, info[0]);
479 |   if (selector.empty())
480 |     return;
481 |   Node* node = SecondArgumentAsNode(info);
482 |   if (!node || !node->IsContainerNode())
483 |     return;
484 | 
485 |   ScriptState* script_state = ScriptState::ForCurrentRealm(info);
486 |   v8::TryCatch try_catch(isolate);
487 |   XPathResult* result = XPathEvaluator::Create()->evaluate(
488 |       nullptr, selector, node, nullptr, XPathResult::kAnyType, ScriptValue(),
489 |       PassThroughException(isolate));
490 |   if (try_catch.HasCaught()) {
491 |     ApplyContextToException(script_state, try_catch.Exception(),
492 |                             v8::ExceptionContext::kOperation, "CommandLineAPI",
493 |                             "$x");
494 |     try_catch.ReThrow();
495 |     return;
496 |   }
497 |   if (!result) {
498 |     return;
499 |   }
500 | 
501 |   if (result->resultType() == XPathResult::kNumberType) {
502 |     bindings::V8SetReturnValue(
503 |         info, result->numberValue(PassThroughException(isolate)));
504 |   } else if (result->resultType() == XPathResult::kStringType) {
505 |     bindings::V8SetReturnValue(
506 |         info, result->stringValue(PassThroughException(isolate)), isolate,
507 |         bindings::V8ReturnValue::kNonNullable);
508 |   } else if (result->resultType() == XPathResult::kBooleanType) {
509 |     bindings::V8SetReturnValue(
510 |         info, result->booleanValue(PassThroughException(isolate)));
511 |   } else {
512 |     v8::Local<v8::Context> context = isolate->GetCurrentContext();
513 |     v8::Local<v8::Array> nodes = v8::Array::New(isolate);
514 |     wtf_size_t index = 0;
515 |     while (Node* next_node =
516 |                result->iterateNext(PassThroughException(isolate))) {
517 |       v8::Local<v8::Value> value =
518 |           ToV8Traits<Node>::ToV8(script_state, next_node);
519 |       if (!CreateDataPropertyInArray(context, nodes, index++, value)
520 |                .FromMaybe(false)) {
521 |         return;
522 |       }
523 |     }
524 |     if (try_catch.HasCaught()) {
525 |       ApplyContextToException(script_state, try_catch.Exception(),
526 |                               v8::ExceptionContext::kOperation,
527 |                               "CommandLineAPI", "$x");
528 |       try_catch.ReThrow();
529 |       return;
530 |     }
531 |     info.GetReturnValue().Set(nodes);
532 |   }
533 | }
