362 |             .setLineNumber(m_lineNumber ? m_lineNumber - 1 : 0)
363 |             .setColumnNumber(m_columnNumber ? m_columnNumber - 1 : 0)
364 |             .build();
365 |     if (m_scriptId) {
366 |       exceptionDetails->setScriptId(String16::fromInteger(m_scriptId));
367 |     }
368 |     if (!m_url.isEmpty()) exceptionDetails->setUrl(m_url);
369 |     if (m_stackTrace) {
370 |       exceptionDetails->setStackTrace(
371 |           m_stackTrace->buildInspectorObjectImpl(inspector->debugger()));
372 |     }
373 |     if (m_contextId) exceptionDetails->setExecutionContextId(m_contextId);
374 |     if (includeException) {
375 |       exceptionDetails->setException(std::move(exception));
376 |     }
377 |     std::unique_ptr<protocol::DictionaryValue> data =
378 |         getAssociatedExceptionData(inspector, session);
379 |     if (data) exceptionDetails->setExceptionMetaData(std::move(data));
380 |     frontend->exceptionThrown(m_timestamp, std::move(exceptionDetails));
381 |     return;
382 |   }
383 |   if (m_origin == V8MessageOrigin::kRevokedException) {
384 |     frontend->exceptionRevoked(m_message, m_revokedExceptionId);
385 |     return;
386 |   }
387 |   if (m_origin == V8MessageOrigin::kConsole) {
388 |     std::unique_ptr<protocol::Array<protocol::Runtime::RemoteObject>>
389 |         arguments = wrapArguments(session, generatePreview);
390 |     V8ConsoleMessageStorage* inspectorStorage =
391 |         inspector->consoleMessageStorage(contextGroupId);
392 |     if (!inspectorStorage || inspectorStorage->id() != storageId) {
393 |       return;
394 |     }
395 |     if (!arguments) {
396 |       arguments =
397 |           std::make_unique<protocol::Array<protocol::Runtime::RemoteObject>>();
398 |       if (!m_message.isEmpty()) {
399 |         std::unique_ptr<protocol::Runtime::RemoteObject> messageArg =
400 |             protocol::Runtime::RemoteObject::create()
401 |                 .setType(protocol::Runtime::RemoteObject::TypeEnum::String)
402 |                 .build();
403 |         messageArg->setValue(protocol::StringValue::create(m_message));
404 |         arguments->emplace_back(std::move(messageArg));
405 |       }
406 |     }
407 |     std::optional<String16> consoleContext;
408 |     if (!m_consoleContext.isEmpty()) consoleContext = m_consoleContext;
409 |     std::unique_ptr<protocol::Runtime::StackTrace> stackTrace;
410 |     if (m_stackTrace) {
411 |       switch (m_type) {
412 |         case ConsoleAPIType::kAssert:
413 |         case ConsoleAPIType::kError:
414 |         case ConsoleAPIType::kTrace:
415 |         case ConsoleAPIType::kWarning:
416 |           stackTrace =
417 |               m_stackTrace->buildInspectorObjectImpl(inspector->debugger());
418 |           break;
419 |         default:
420 |           stackTrace =
421 |               m_stackTrace->buildInspectorObjectImpl(inspector->debugger(), 0);
422 |           break;
423 |       }
424 |     }
425 |     frontend->consoleAPICalled(
426 |         consoleAPITypeValue(m_type), std::move(arguments), m_contextId,
427 |         m_timestamp, std::move(stackTrace), std::move(consoleContext));
428 |     return;
429 |   }
430 |   UNREACHABLE();
431 | }
