141 | void WorkerThreadDebugger::ExceptionThrown(WorkerThread* worker_thread,
142 |                                            ErrorEvent* event) {
143 |   worker_thread->GetWorkerReportingProxy().ReportConsoleMessage(
144 |       mojom::ConsoleMessageSource::kJavaScript,
145 |       mojom::ConsoleMessageLevel::kError, event->MessageForConsole(),
