147 | 
148 |   const String default_message = "Uncaught";
149 |   ScriptState* script_state =
150 |       worker_thread->GlobalScope()->ScriptController()->GetScriptState();
151 |   if (script_state && script_state->ContextIsValid()) {
152 |     ScriptState::Scope scope(script_state);
