154 |     v8::Local<v8::Value> exception =
155 |         error.IsEmpty()
156 |             ? v8::Local<v8::Value>(v8::Null(script_state->GetIsolate()))
157 |             : error.V8Value();
158 |     SourceLocation* location = event->Location();
159 |     String message = event->MessageForConsole();
160 |     String url = location->Url();
161 |     GetV8Inspector()->exceptionThrown(
162 |         script_state->GetContext(), ToV8InspectorStringView(default_message),
163 |         exception, ToV8InspectorStringView(message),
164 |         ToV8InspectorStringView(url), location->LineNumber(),
165 |         location->ColumnNumber(), location->TakeStackTrace(),
166 |         location->ScriptId());
167 |   }
