600 | ThreadDebuggerCommonImpl::valueSubtype(v8::Local<v8::Value> value) {
601 |   static const char kNode[] = "node";
602 |   static const char kArray[] = "array";
603 |   static const char kError[] = "error";
604 |   static const char kBlob[] = "blob";
605 |   static const char kTrustedType[] = "trustedtype";
606 | 
607 |   if (V8Node::HasInstance(isolate_, value)) {
608 |     return ToV8InspectorStringBuffer(kNode);
609 |   }
610 |   if (V8NodeList::HasInstance(isolate_, value) ||
611 |       V8DOMTokenList::HasInstance(isolate_, value) ||
612 |       V8HTMLCollection::HasInstance(isolate_, value) ||
613 |       V8HTMLAllCollection::HasInstance(isolate_, value)) {
614 |     return ToV8InspectorStringBuffer(kArray);
615 |   }
616 |   if (V8DOMException::HasInstance(isolate_, value)) {
617 |     return ToV8InspectorStringBuffer(kError);
618 |   }
619 |   if (V8Blob::HasInstance(isolate_, value)) {
620 |     return ToV8InspectorStringBuffer(kBlob);
621 |   }
622 |   if (V8TrustedHTML::HasInstance(isolate_, value) ||
623 |       V8TrustedScript::HasInstance(isolate_, value) ||
624 |       V8TrustedScriptURL::HasInstance(isolate_, value)) {
625 |     return ToV8InspectorStringBuffer(kTrustedType);
626 |   }
627 |   return nullptr;
628 | }
