761 | void ThreadDebuggerCommonImpl::installAdditionalCommandLineAPI(
762 |     v8::Local<v8::Context> context,
763 |     v8::Local<v8::Object> object) {
764 |   CreateFunctionProperty(
765 |       context, object, "getEventListeners",
766 |       ThreadDebuggerCommonImpl::GetEventListenersCallback,
767 |       "function getEventListeners(node) { [Command Line API] }",
768 |       v8::SideEffectType::kHasNoSideEffect);
769 | 
770 |   CreateFunctionProperty(
771 |       context, object, "getAccessibleName",
772 |       ThreadDebuggerCommonImpl::GetAccessibleNameCallback,
773 |       "function getAccessibleName(node) { [Command Line API] }",
774 |       v8::SideEffectType::kHasNoSideEffect);
775 | 
776 |   CreateFunctionProperty(
777 |       context, object, "getAccessibleRole",
778 |       ThreadDebuggerCommonImpl::GetAccessibleRoleCallback,
779 |       "function getAccessibleRole(node) { [Command Line API] }",
780 |       v8::SideEffectType::kHasNoSideEffect);
781 | 
782 |   v8::Isolate* isolate = v8::Isolate::GetCurrent();
783 |   ScriptEvaluationResult result =
784 |       ClassicScript::CreateUnspecifiedScript(
785 |           "(function(e) { console.log(e.type, e); })",
786 |           ScriptSourceLocationType::kInternal)
787 |           ->RunScriptOnScriptStateAndReturnValue(
788 |               ScriptState::From(isolate, context));
789 |   if (result.GetResultType() != ScriptEvaluationResult::ResultType::kSuccess) {
790 |     // On pages where scripting is disabled or CSP sandbox directive is used,
791 |     // this can be blocked and thus early exited here.
792 |     // This is probably OK because `monitorEvents()` console API is anyway not
793 |     // working on such pages. For more discussion see
794 |     // https://crrev.com/c/3258735/9/third_party/blink/renderer/core/inspector/thread_debugger.cc#529
795 |     return;
796 |   }
797 | 
798 |   v8::Local<v8::Value> function_value = result.GetSuccessValue();
799 |   DCHECK(function_value->IsFunction());
800 |   CreateFunctionPropertyWithData(
801 |       context, object, "monitorEvents",
802 |       ThreadDebuggerCommonImpl::MonitorEventsCallback, function_value,
803 |       "function monitorEvents(object, [types]) { [Command Line API] }",
804 |       v8::SideEffectType::kHasSideEffect);
805 |   CreateFunctionPropertyWithData(
806 |       context, object, "unmonitorEvents",
807 |       ThreadDebuggerCommonImpl::UnmonitorEventsCallback, function_value,
808 |       "function unmonitorEvents(object, [types]) { [Command Line API] }",
809 |       v8::SideEffectType::kHasSideEffect);
810 | }
