886 | void ThreadDebuggerCommonImpl::SetMonitorEventsCallback(
887 |     const v8::FunctionCallbackInfo<v8::Value>& info,
888 |     bool enabled) {
889 |   EventTarget* event_target = FirstArgumentAsEventTarget(info);
890 |   if (!event_target)
891 |     return;
892 |   Vector<String> types = NormalizeEventTypes(info);
893 |   DCHECK(!info.DataV2().IsEmpty() &&
894 |          info.DataV2().As<v8::Value>()->IsFunction());
895 |   V8EventListener* event_listener =
896 |       V8EventListener::Create(info.DataV2().As<v8::Value>().As<v8::Function>());
897 |   for (wtf_size_t i = 0; i < types.size(); ++i) {
898 |     if (enabled)
899 |       event_target->addEventListener(AtomicString(types[i]), event_listener);
900 |     else
901 |       event_target->removeEventListener(AtomicString(types[i]), event_listener);
902 |   }
903 | }
