917 | // static
918 | void ThreadDebuggerCommonImpl::GetAccessibleNameCallback(
919 |     const v8::FunctionCallbackInfo<v8::Value>& info) {
920 |   if (info.Length() < 1)
921 |     return;
922 | 
923 |   v8::Isolate* isolate = info.GetIsolate();
924 |   v8::Local<v8::Value> value = info[0];
925 | 
926 |   Node* node = V8Node::ToWrappable(isolate, value);
927 |   if (node && !node->GetLayoutObject())
928 |     return;
