245 | void InstallContextFunction(Isolate* isolate, DirectHandle<JSObject> target,
246 |                             const char* name, Builtin builtin,
247 |                             DirectHandle<Context> context) {
248 |   Factory* const factory = isolate->factory();
249 | 
250 |   DirectHandle<Map> map = isolate->function_without_prototype_map();
251 | 
252 |   DirectHandle<String> name_string = factory->InternalizeUtf8String(name);
253 | 
254 |   DirectHandle<SharedFunctionInfo> info =
255 |       factory->NewSharedFunctionInfoForBuiltin(name_string, builtin, 1,
256 |                                                kDontAdapt);
257 |   info->set_language_mode(LanguageMode::kSloppy);
258 |   info->set_native(true);
259 | 
260 |   DirectHandle<JSFunction> fun =
261 |       Factory::JSFunctionBuilder{isolate, info, context}.set_map(map).Build();
262 | 
263 |   JSObject::AddProperty(isolate, target, name_string, fun, NONE);
264 | }
265 | 
266 | }  // namespace
