268 | BUILTIN(ConsoleContext) {
269 |   HandleScope scope(isolate);
270 |   Factory* const factory = isolate->factory();
271 | 
272 |   isolate->CountUsage(v8::Isolate::UseCounterFeature::kConsoleContext);
273 | 
274 |   // Generate a unique ID for the new `console.context`
275 |   // and convert the parameter to a string (defaults to
276 |   // 'anonymous' if unspecified).
277 |   DirectHandle<String> context_name = factory->anonymous_string();
278 |   if (args.length() > 1) {
279 |     ASSIGN_RETURN_FAILURE_ON_EXCEPTION(isolate, context_name,
280 |                                        Object::ToString(isolate, args.at(1)));
281 |   }
282 |   int context_id = isolate->last_console_context_id() + 1;
283 |   isolate->set_last_console_context_id(context_id);
284 | 
285 |   DirectHandle<SharedFunctionInfo> info =
286 |       factory->NewSharedFunctionInfoForBuiltin(
287 |           factory->InternalizeUtf8String("Context"), Builtin::kIllegal, 0,
288 |           kDontAdapt);
289 |   info->set_language_mode(LanguageMode::kSloppy);
290 | 
291 |   DirectHandle<JSFunction> cons =
292 |       Factory::JSFunctionBuilder{isolate, info, isolate->native_context()}
293 |           .Build();
294 | 
295 |   DirectHandle<JSObject> prototype =
296 |       factory->NewJSObject(isolate->object_function());
297 |   JSFunction::SetPrototype(isolate, cons, prototype);
298 | 
299 |   DirectHandle<JSObject> console_context =
300 |       factory->NewJSObject(cons, AllocationType::kOld);
301 |   DCHECK(IsJSObject(*console_context));
302 | 
303 |   DirectHandle<Context> context = factory->NewBuiltinContext(
304 |       isolate->native_context(), CONSOLE_CONTEXT_SLOTS);
305 |   context->SetNoCell(CONSOLE_CONTEXT_ID_INDEX, Smi::FromInt(context_id));
306 |   context->SetNoCell(CONSOLE_CONTEXT_NAME_INDEX, *context_name);
307 | 
308 | #define CONSOLE_BUILTIN_SETUP(call, name, ...)            \
309 |   InstallContextFunction(isolate, console_context, #name, \
310 |                          Builtin::kConsole##call, context);
311 |   CONSOLE_METHOD_LIST(CONSOLE_BUILTIN_SETUP)
312 |   CONSOLE_METHOD_WITH_FORMATTER_LIST(CONSOLE_BUILTIN_SETUP)
313 |   CONSOLE_BUILTIN_SETUP(Time, time)
314 |   CONSOLE_BUILTIN_SETUP(TimeLog, timeLog)
315 |   CONSOLE_BUILTIN_SETUP(TimeEnd, timeEnd)
316 |   CONSOLE_BUILTIN_SETUP(TimeStamp, timeStamp)
317 | #undef CONSOLE_BUILTIN_SETUP
318 |   InstallContextFunction(isolate, console_context, "assert",
319 |                          Builtin::kFastConsoleAssert, context);
320 | 
321 |   return *console_context;
322 | }
