277 | /**
278 |  * Each JS task object created via `console.createTask` has a corresponding
279 |  * `TaskInfo` object on the C++ side (in a 1:1 relationship).
280 |  *
281 |  * `TaskInfo` is an Oilpan object wrapped in the JS task object.
282 |  *
283 |  * `TaskInfo` holds all the necessary information we need to properly cancel
284 |  * the corresponding async task when the JS task object gets GC'ed and its
285 |  * destructor runs.
286 |  */
287 | class TaskInfo : public v8::Object::Wrappable {
288 |  public:
289 |   static constexpr v8::CppHeapPointerTag kPointerTag =
290 |       v8::internal::kInspectorTaskInfoTag;
291 | 
292 |   TaskInfo(v8::Isolate* isolate, V8Console* console);
293 |   ~TaskInfo() override;
294 | 
295 |   // For these task IDs we duplicate the ID logic from blink and use even
296 |   // pointers compared to the odd IDs we use for promises. This guarantees that
297 |   // we don't have any conflicts between task IDs.
298 |   void* Id() const {
299 |     return reinterpret_cast<void*>(reinterpret_cast<uintptr_t>(m_id.get())
300 |                                    << 1);
301 |   }
302 | 
303 |   void Trace(cppgc::Visitor* visitor) const override;
304 |   static void runTask(const v8::FunctionCallbackInfo<v8::Value>& info);
305 | 
306 |   // We store an off-heap pointer to the isolate so we can safely look up the
307 |   // inspector during ~TaskInfo() via v8::debug::GetInspector(m_isolate).
308 |   // Dereferencing m_console during sweeping is prohibited by Oilpan rules
309 |   // since V8Console is an on-heap object that might have already been swept.
310 |   // Furthermore, GetInspector provides robust protection against teardown
311 |   // races: if the inspector shuts down before TaskInfo is destructed, V8
312 |   // automatically clears the isolate's inspector pointer, ensuring
313 |   // GetInspector safely returns nullptr.
314 |   v8::Isolate* m_isolate;
315 |   cppgc::Member<V8Console> m_console;
316 |   // Task IDs must be unique across the entire process, but they are generated
317 |   // in multiple places (e.g. in Blink), making synchronization complex. To
318 |   // avoid coordinated ID generation, we use the memory allocator as an ID
319 |   // generator by using an allocation address as the ID. In principle, we could
320 |   // use the `this` pointer, but since TaskInfo is an Oilpan object, a future
321 |   // moving GC could cause the `this` pointer address to change over time.
322 |   // Therefore, we perform the smallest possible allocation and use the address
323 |   // of that memory. It is stored in a std::unique_ptr so that the memory gets
324 |   // deallocated eventually.
325 |   std::unique_ptr<char> m_id;
326 | };
